#include <bits/stdc++.h>
using namespace std;const int N=2005,P=998244353;int x[N],y[N],a[N],b[N],c[N];int q(int a,int n=P-2){int r=1;for(;n;n>>=1,a=1LL*a*a%P)if(n&1)r=1LL*r*a%P;return r;}int main(){ios::sync_with_stdio(0);cin.tie(0);int n,k;cin>>n>>k;for(int i=0;i<n;i++)cin>>x[i]>>y[i];for(int i=0;i<n;i++){memset(a,0,(n+1)*sizeof(int));a[0]=1;int d=0;long long z=1;for(int j=0;j<n;j++)if(i!=j){memset(b,0,(n+1)*sizeof(int));for(int l=0;l<=d;l++)b[l]=(b[l]-1LL*a[l]*x[j]%P+P)%P,b[l+1]=(b[l+1]+a[l])%P;memcpy(a,b,(n+1)*sizeof(int));d++;z=z*(x[i]-x[j]+P)%P;}z=1LL*y[i]*q(z)%P;for(int j=0;j<n;j++)c[j]=(c[j]+z*a[j])%P;}long long r=0;for(int i=n-1;i>=0;i--)r=(r*k+c[i])%P;cout<<r<<'\n';}
